  "\u5907\u6CE8\u540D\uFF0C\u5982\u300C\u5DE5\u4F5C\u53F7\u300D": "\u0417\u0430\u043C\u0435\u0442\u043A\u0430, \u043D\u0430\u043F\u0440. \xAB\u0440\u0430\u0431\u043E\u0447\u0438\u0439\xBB",
  "\u5206\u7EC4\u540D\uFF0C\u5982\u300C\u5DE5\u4F5C\u53F7\u300D": "\u0418\u043C\u044F \u0433\u0440\u0443\u043F\u043F\u044B, \u043D\u0430\u043F\u0440. \xAB\u0440\u0430\u0431\u043E\u0447\u0438\u0435\xBB",
  "\u6B63\u5728\u6821\u9A8C\u767B\u5F55\u6001\u5E76\u51C6\u5907\u767B\u5F55\u7A97\u53E3\u2026\u2026": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0441\u0435\u0441\u0441\u0438\u0438 \u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430 \u043E\u043A\u043D\u0430 \u0432\u0445\u043E\u0434\u0430\u2026",
  "\u8FD9\u6761\u8D26\u53F7\u6821\u9A8C\u901A\u8FC7\uFF0C\u4E0D\u9700\u8981\u91CD\u65B0\u767B\u5F55": "\u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D, \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 \u0432\u0445\u043E\u0434 \u043D\u0435 \u043D\u0443\u0436\u0435\u043D",
  "\u672A\u77E5\u539F\u56E0": "\u041D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u0430\u044F \u043F\u0440\u0438\u0447\u0438\u043D\u0430",
  "\u767B\u5F55\u7A97\u53E3\u5DF2\u6253\u5F00": "\u041E\u043A\u043D\u043E \u0432\u0445\u043E\u0434\u0430 \u043E\u0442\u043A\u0440\u044B\u0442\u043E",
  "\u5DF2\u6355\u83B7\u5E76\u4FDD\u5B58\u51ED\u8BC1\u3002": "\u0423\u0447\u0451\u0442\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0437\u0430\u0445\u0432\u0430\u0447\u0435\u043D\u044B \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u044B.",
  "\u2705 \u5DF2\u5207\u6362\uFF08\u4E0B\u4E00\u6B21\u8BF7\u6C42\u751F\u6548\uFF09": "\u2705 \u041F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u043E (\u0441\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0437\u0430\u043F\u0440\u043E\u0441\u0430)",
  "\u5207\u6362\u4E2D\u2026": "\u041F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435\u2026",
  "\u5207\u6362\u4E2D\u2026\u2026": "\u041F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435\u2026",
  "\u6B63\u5728\u6821\u9A8C\u767B\u5F55\u6001\u5E76\u5207\u6362\u2026\u2026": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0441\u0435\u0441\u0441\u0438\u0438 \u0438 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435\u2026",
  "\u5DF2\u79FB\u9664\u8BE5\u8D26\u53F7\uFF08\u51ED\u8BC1\u5DF2\u5220\u9664\uFF09": "\u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u0443\u0434\u0430\u043B\u0451\u043D (\u0443\u0447\u0451\u0442\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0441\u0442\u0451\u0440\u0442\u044B)",
  "\u8D26\u53F7\u5E93\u8BFB\u53D6\u5931\u8D25\uFF1A": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443: ",
  "\u6B63\u5728\u6821\u9A8C\u300C": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \xAB",
  "\u300D\u5E76\u51C6\u5907\u767B\u5F55\u7A97\u53E3\u2026\u2026": "\xBB \u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430 \u043E\u043A\u043D\u0430 \u0432\u0445\u043E\u0434\u0430\u2026",
  "\u6253\u5F00\u767B\u5F55\u7A97\u53E3\u5931\u8D25\uFF1A": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043E\u043A\u043D\u043E \u0432\u0445\u043E\u0434\u0430: ",
  "\uFF08\u53EF\u6539\u7528\u300C\u624B\u52A8\u7C98\u8D34 Token\u300D\uFF09": " (\u043C\u043E\u0436\u043D\u043E \xAB\u0412\u0441\u0442\u0430\u0432\u0438\u0442\u044C Token \u0432\u0440\u0443\u0447\u043D\u0443\u044E\xBB)",
  "\u300D\u7684\u51ED\u8BC1\u5DF2\u539F\u5730\u66F4\u65B0\uFF08\u540C\u4E00\u6761\u8BB0\u5F55\u3001\u5F53\u524D\u8D26\u53F7\u672A\u53D8\uFF09\uFF0C\u65E7\u7684\u5931\u8D25\u6807\u8BB0\u4E5F\u6E05\u6389\u4E86\u3002": "\xBB: \u0443\u0447\u0451\u0442\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u044B \u043D\u0430 \u043C\u0435\u0441\u0442\u0435 (\u0442\u0430 \u0436\u0435 \u0437\u0430\u043F\u0438\u0441\u044C, \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u043D\u0435 \u043C\u0435\u043D\u044F\u043B\u0441\u044F), \u0441\u0442\u0430\u0440\u044B\u0435 \u043C\u0435\u0442\u043A\u0438 \u043E\u0448\u0438\u0431\u043E\u043A \u0441\u043D\u044F\u0442\u044B.",
  "\u300D\u5DF2\u52A0\u5165\u8D26\u53F7\u5E93 \u2014\u2014 \u5F53\u524D\u4F7F\u7528\u7684\u8D26\u53F7\u6CA1\u6709\u6539\u53D8\u3002": "\xBB \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D \u0432 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u2014 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u0441\u044F.",
  "\u91CD\u65B0\u767B\u5F55\u5931\u8D25\uFF1A": "\u041F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 \u0432\u0445\u043E\u0434 \u043D\u0435 \u0443\u0434\u0430\u043B\u0441\u044F: ",
  "\u5C1A\u672A\u6821\u9A8C": "\u0435\u0449\u0451 \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D",
  "\u6355\u83B7": "\u0437\u0430\u0445\u0432\u0430\u0442",
  "\u6700\u8FD1\u6821\u9A8C": "\u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430",
  // ── Manual token ──────────────────────────────────────────────
  "\u624B\u52A8\u7C98\u8D34 token": "\u0412\u0441\u0442\u0430\u0432\u0438\u0442\u044C Token \u0432\u0440\u0443\u0447\u043D\u0443\u044E",
  "\u624B\u52A8\u7C98\u8D34 Token": "\u0412\u0441\u0442\u0430\u0432\u0438\u0442\u044C Token \u0432\u0440\u0443\u0447\u043D\u0443\u044E",
  "\u8F93\u5165 Token": "\u0412\u0441\u0442\u0430\u0432\u044C\u0442\u0435 Token",
  "\u4FDD\u5B58\u5E76\u9A8C\u8BC1": "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C",
  "\u6B63\u5728\u6821\u9A8C token\u2026\u2026": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 token\u2026",
  "\u4FDD\u5B58\u4E2D\u2026\u2026": "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435\u2026",
  "\u2460 \u5728\u6D4F\u89C8\u5668\u91CC\u6B63\u5E38\u767B\u5F55\uFF1B\u2461\u6309 F12 \u2192 Console\uFF0C\u7C98\u8D34\u4E0B\u65B9\u300C\u624B\u52A8\u7C98\u8D34 Token\u300D\u5361\u91CC\u7684\u90A3\u884C\u547D\u4EE4\uFF1B": "\u2460 \u0412\u043E\u0439\u0434\u0438\u0442\u0435 \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435 \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u043E; \u2461 F12 \u2192 Console, \u0432\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u0438\u0437 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \xAB\u0412\u0441\u0442\u0430\u0432\u0438\u0442\u044C Token \u0432\u0440\u0443\u0447\u043D\u0443\u044E\xBB;",
  "\u2462 \u628A\u6253\u5370\u51FA\u6765\u7684\u7ED3\u679C\u7C98\u5230\u90A3\u5F20\u5361\u7684\u8F93\u5165\u6846 \u2192 \u70B9\u300C\u4FDD\u5B58\u5E76\u9A8C\u8BC1\u300D\u3002": "\u2462 \u0412\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0432 \u043F\u043E\u043B\u0435 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0438 \u2192 \xAB\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C\xBB.",
  // ── Models ────────────────────────────────────────────────────
  "\u53EF\u7528\u6A21\u578B\uFF08\u7F51\u9875\u514D\u8D39\uFF09": "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043C\u043E\u0434\u0435\u043B\u0438 (\u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0439 \u0432\u0435\u0431)",
  "\u8FDE\u901A\u6027\u6D4B\u8BD5": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0441\u0432\u044F\u0437\u0438",
