  "DSH \u8BA4\u4E3A\u6A21\u578B\u80FD\u88C5\u591A\u5C11": "\u0421\u043A\u043E\u043B\u044C\u043A\u043E, \u043F\u043E \u043C\u043D\u0435\u043D\u0438\u044E DSH, \u0432\u043B\u0435\u0437\u0430\u0435\u0442 \u0432 \u043C\u043E\u0434\u0435\u043B\u044C",
  "\u5BF9\u5916\u58F0\u660E\u7684\u4E0A\u4E0B\u6587\u7A97\u53E3\u5927\u5C0F": "\u0417\u0430\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0440\u0430\u0437\u043C\u0435\u0440 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u043D\u043E\u0433\u043E \u043E\u043A\u043D\u0430",
  // ── Gate / anti-abuse ─────────────────────────────────────────
  "\u8BF7\u6C42\u8282\u6D41\uFF08\u9632\u98CE\u63A7\uFF09": "\u0422\u0440\u043E\u0442\u0442\u043B\u0438\u043D\u0433 \u0437\u0430\u043F\u0440\u043E\u0441\u043E\u0432 (\u0430\u043D\u0442\u0438-\u043B\u0438\u043C\u0438\u0442\u044B)",
