  "\u81EA\u52A8\u6362\u53F7": "\u0410\u0432\u0442\u043E\u0441\u043C\u0435\u043D\u0430 \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0430",
  "\u51ED\u8BC1\u5931\u6548\u5373\u6362": "\u041C\u0435\u043D\u044F\u0442\u044C \u043F\u0440\u0438 \u043D\u0435\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0443\u0447\u0451\u0442\u043D\u044B\u0445 \u0434\u0430\u043D\u043D\u044B\u0445",
