  "\u95F4\u9694\u4E0B\u9650": "\u041C\u0438\u043D. \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B",
  "\u95F4\u9694\u4E0A\u9650": "\u041C\u0430\u043A\u0441. \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B",
  "\u76F8\u90BB\u5BF9\u8BDD\u95F4\u9694": "\u0418\u043D\u0442\u0435\u0440\u0432\u0430\u043B \u043C\u0435\u0436\u0434\u0443 \u0434\u0438\u0430\u043B\u043E\u0433\u0430\u043C\u0438",
