  "\u56FA\u5B9A\u95F4\u9694 {0}ms\uFF08\u4E0A\u4E0B\u9650\u76F8\u7B49\uFF09\u3002\u5EFA\u8BAE\u62C9\u5F00\u6210\u533A\u95F4 \u2014\u2014 \u56FA\u5B9A\u503C\u65B9\u5DEE\u22480\uFF0C\u662F\u660E\u663E\u7684\u300C\u5B9A\u65F6\u5668\u7279\u5F81\u300D\u3002": "\u0424\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B {0} ms (\u043C\u0438\u043D=\u043C\u0430\u043A\u0441). \u041B\u0443\u0447\u0448\u0435 \u0437\u0430\u0434\u0430\u0442\u044C \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u2014 \u043D\u0443\u043B\u0435\u0432\u0430\u044F \u0434\u0438\u0441\u043F\u0435\u0440\u0441\u0438\u044F \u0432\u044B\u0433\u043B\u044F\u0434\u0438\u0442 \u043A\u0430\u043A \u0442\u0430\u0439\u043C\u0435\u0440.",
