  "\u7ACB\u5373\uFF1A\u8C03\u7528\u7ED3\u675F\u540E 1.5 \u79D2\u5220\u6389\uFF08\u8001\u884C\u4E3A\uFF0C\u6BCF\u8F6E\u591A\u4E00\u4E2A\u5220\u9664\u8BF7\u6C42\uFF09\u3002": "\u0421\u0440\u0430\u0437\u0443: \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0447\u0435\u0440\u0435\u0437 1.5 \u0441 \u043F\u043E\u0441\u043B\u0435 \u0432\u044B\u0437\u043E\u0432\u0430 (\u0441\u0442\u0430\u0440\u043E\u0435 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435, \u043B\u0438\u0448\u043D\u0438\u0439 delete-\u0437\u0430\u043F\u0440\u043E\u0441 \u043A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0443\u043D\u0434).",
  "\u5EF6\u8FDF\uFF1A\u8FD9\u4E00\u8F6E\u6512\u591F {0} \u4E2A\u3001\u6216\u6700\u591A\u7B49 {1} \u79D2\u5C31\u96C6\u4E2D\u6E05\u7406\uFF0C\u5E76\u4F18\u5148\u7528\u4E00\u4E2A\u8BF7\u6C42\u6279\u91CF\u5220 \u2014\u2014": "\u0421 \u0437\u0430\u0434\u0435\u0440\u0436\u043A\u043E\u0439: \u043A\u043E\u043F\u0438\u0442\u044C \u0434\u043E {0} \u0448\u0442. \u0438\u043B\u0438 \u0436\u0434\u0430\u0442\u044C \u0434\u043E {1} \u0441, \u0437\u0430\u0442\u0435\u043C \u043F\u0430\u043A\u0435\u0442\u043D\u0430\u044F \u043E\u0447\u0438\u0441\u0442\u043A\u0430 \u043E\u0434\u043D\u0438\u043C \u0437\u0430\u043F\u0440\u043E\u0441\u043E\u043C \u2014",
